1	// pattern: Mixed (unavoidable)
2	//
3	// Client-side Shamir share generation for the DID ceremony (the ceremony inversion):
4	// the wallet — not the server — generates the recovery seed, derives the recovery
5	// rotation key from it, and splits the seed 2-of-3 into v2 share envelopes. Custos
6	// receives exactly one share (the Share 2 envelope, deposited with the ceremony
7	// request) and never sees the seed or the other shares, so no server backup can ever
8	// hold reconstruction material.
9	//
10	// Retry resilience lives here too: the generated set is persisted in a Keychain
11	// staging slot (`ceremony-staging` — transient working material, distinct from the
12	// durable per-DID `recovery-share-1:{did}` slot) BEFORE any network call, so a retry reuses the
13	// identical set (same set_id) instead of orphaning a prior attempt's escrow deposit.
14	// The staging record holds the three envelopes only — the seed is recomputed from
15	// Shares 1+2 on load, and every load re-validates each envelope's checksum and
16	// cross-checks set_ids. A present-but-unreadable record **fails closed**
17	// (`StagingCorrupt`) rather than regenerating: it may be the exact set a prior
18	// attempt already bound to a genesis op and escrowed, so overwriting it would
19	// permanently destroy the recovery seed. Only a genuinely absent slot — or one
20	// staged for different ceremony inputs, which a new ceremony explicitly abandons —
21	// permits fresh generation.
22	//
23	// Teardown order is load-bearing: `clear_staging` runs only after Share 1 has
24	// verifiably reached its durable slot and the user has confirmed saving Share 3
25	// (`confirm_share_backup` in lib.rs drives that), because until then the staging
26	// slot is the only durable home of the seed material.
27	
28	use rand_core::{OsRng, RngCore};
29	use serde::{Deserialize, Serialize};
30	use zeroize::Zeroizing;
31	
32	use crate::keychain;
33	
34	/// Keychain account for the in-flight *create* ceremony share set. Transient working
35	/// material — deleted by [`clear_staging`] once the ceremony is confirmed.
36	pub const STAGING_ACCOUNT: &str = "ceremony-staging";
37	
38	/// Keychain account for an in-flight *re-key* share set, scoped per DID.
39	///
40	/// Re-key (moving an existing old-model account onto a client-generated recovery key)
41	/// runs its own ceremony against an existing identity, so it gets a slot keyed by DID
42	/// rather than sharing the single create-flow slot. A per-DID slot is load-bearing for
43	/// safety: unlike the create flow, a re-key must NEVER abandon a staged set because a
44	/// *different* DID's re-key started — a staged set whose rotation op has already landed
45	/// is the only durable home of that account's new recovery seed. Keying the account by
46	/// DID means one identity's re-key can never overwrite or orphan another's.
47	fn rekey_staging_account(did: &str) -> String {
48	    format!("rekey-staging:{did}")
49	}
50	
51	/// Bumped only on a breaking staging-record format change; a mismatched version
52	/// reads as corrupt and fails closed (`StagingCorrupt`).
53	const STAGING_VERSION: u32 = 1;
54	
55	#[derive(Debug, thiserror::Error)]
56	pub enum ShareCeremonyError {
57	    #[error("crypto failure: {0}")]
58	    Crypto(#[from] crypto::CryptoError),
59	    #[error("OS RNG unavailable: {0}")]
60	    Rng(String),
61	    #[error("keychain failure: {0}")]
62	    Keychain(#[from] keychain::KeychainError),
63	    /// A staging record exists but could not be read or validated. Fail closed: the
64	    /// record may be the exact set already bound to a genesis op (and escrowed) by a
65	    /// prior attempt, so it must never be silently overwritten with fresh material —
66	    /// that would permanently destroy the recovery seed.
67	    #[error("ceremony staging record is present but unreadable: {0}")]
68	    StagingCorrupt(String),
69	}
70	
71	/// The wallet-generated share set for one DID ceremony attempt (or a staged retry).
72	///
73	/// Encoded share strings are share material and ride in [`Zeroizing`] buffers, matching
74	/// the crypto crate's rule that share material never lands in non-zeroizing storage.
75	pub struct CeremonyShareSet {
76	    /// did:key URI of the recovery rotation key derived from the seed — goes into the
77	    /// genesis op's `rotationKeys` (slot \[1\]) and the ceremony request's `recoveryKey`.
78	    pub recovery_key_id: String,
79	    /// Base32 v2 envelope of Share 1 — written to the durable per-DID `recovery-share-1:{did}`
80	    /// slot after promotion.
81	    pub share1: Zeroizing<String>,
82	    /// Base32 v2 envelope of Share 2 — the escrow deposit sent to Custos.
83	    pub share2: Zeroizing<String>,
84	    /// Base32 v2 envelope of Share 3 — the user's manual-backup copy (QR form).
85	    pub share3: Zeroizing<String>,
86	    /// Share 3 rendered as the BIP-39-style word phrase (identical 42 bytes).
87	    pub share3_words: Zeroizing<String>,
88	}
89	
90	/// The staging slot's JSON payload. The seed is deliberately absent — it is
91	/// `combine_envelopes(share1, share2)`, so storing it again would only widen the
92	/// secret surface.
93	///
94	/// The share fields are share material held in plain `String`s while the record is
95	/// (de)serialized, so the record wipes them on drop (`Drop` below) — the same rule as
96	/// every other in-memory home of share material.
97	#[derive(Serialize, Deserialize)]
98	struct StagingRecord {
99	    version: u32,
100	    /// The ceremony inputs this set was generated for. A retry with different inputs
101	    /// (different handle, different PDS) is a different ceremony — regenerate.
102	    handle: String,
103	    pds_url: String,
104	    share1: String,
105	    share2: String,
106	    share3: String,
107	}
108	
109	impl Drop for StagingRecord {
110	    fn drop(&mut self) {
111	        use zeroize::Zeroize;
112	        self.share1.zeroize();
113	        self.share2.zeroize();
114	        self.share3.zeroize();
115	    }
116	}
117	
118	/// Load the staged *create*-ceremony share set for `(handle, pds_url)` if a valid one
119	/// exists, else generate a fresh set and stage it — always BEFORE the caller makes any
120	/// network call, so a mid-ceremony failure retries with the identical set (same
121	/// `set_id`).
122	pub fn load_or_create(handle: &str, pds_url: &str) -> Result<CeremonyShareSet, ShareCeremonyError> {
123	    load_or_create_in_account(STAGING_ACCOUNT, handle, pds_url)
124	}
125	
126	/// Load-or-create for a re-key ceremony: same generation/reload semantics as
127	/// [`load_or_create`], but staged in the per-DID re-key slot (see
128	/// [`rekey_staging_account`]). The `(did, pds_url)` pair is the discriminator, so a
129	/// resumed re-key for the same DID always reloads the identical set — a re-key never
130	/// abandons a staged set the way a create ceremony does on changed inputs.
131	pub fn load_or_create_for_rekey(
132	    did: &str,
133	    pds_url: &str,
134	) -> Result<CeremonyShareSet, ShareCeremonyError> {
135	    load_or_create_in_account(&rekey_staging_account(did), did, pds_url)
136	}
137	
138	/// Shared implementation: load the staged set from `account` (bound to the
139	/// `(discriminator_a, discriminator_b)` pair), else generate a fresh set and stage it
140	/// there before returning.
141	fn load_or_create_in_account(
142	    account: &str,
143	    discriminator_a: &str,
144	    discriminator_b: &str,
145	) -> Result<CeremonyShareSet, ShareCeremonyError> {
146	    if let Some(staged) = load_staged(account, discriminator_a, discriminator_b)? {
147	        return Ok(staged);
148	    }
149	
150	    let mut seed = Zeroizing::new([0u8; 32]);
151	    OsRng
152	        .try_fill_bytes(seed.as_mut())
153	        .map_err(|e| ShareCeremonyError::Rng(e.to_string()))?;
154	    let mut set_id_bytes = [0u8; 4];
155	    OsRng
156	        .try_fill_bytes(&mut set_id_bytes)
157	        .map_err(|e| ShareCeremonyError::Rng(e.to_string()))?;
158	    let set_id = u32::from_be_bytes(set_id_bytes);
159	
160	    let envelopes = crypto::split_secret_into_envelopes(&seed, set_id)?;
161	    let recovery = crypto::derive_recovery_keypair(&seed)?;
162	
163	    let share1 = envelopes[0].encode_share();
164	    let share2 = envelopes[1].encode_share();
165	    let share3 = envelopes[2].encode_share();
166	    let share3_words = envelopes[2].encode_share_words();
167	
168	    // Stage before returning: from here on, a retry of the same ceremony must reuse
169	    // this exact set. The serialized record is share material — zeroized after the
170	    // Keychain write.
171	    let record = Zeroizing::new(
172	        serde_json::to_string(&StagingRecord {
173	            version: STAGING_VERSION,
174	            handle: discriminator_a.to_string(),
175	            pds_url: discriminator_b.to_string(),
176	            share1: share1.to_string(),
177	            share2: share2.to_string(),
178	            share3: share3.to_string(),
179	        })
180	        .expect("staging record serialization cannot fail"),
181	    );
182	    keychain::store_item(account, record.as_bytes())?;
183	
184	    Ok(CeremonyShareSet {
185	        recovery_key_id: recovery.key_id.0,
186	        share1,
187	        share2,
188	        share3,
189	        share3_words,
190	    })
191	}
192	
193	/// Read and validate the staging slot.
194	///
195	/// Fail-closed contract: only two outcomes permit generating fresh material —
196	/// `Ok(None)` for a genuinely absent slot, or for a slot staged under *different
197	/// ceremony inputs* (a new handle/PDS is a new ceremony; starting one is the user's
198	/// explicit abandonment of the old attempt, whose set can never bind to this
199	/// ceremony's genesis op). Every other defect — a transient read error, unparseable
200	/// JSON, an unsupported version, a corrupt envelope, cross-set envelopes, a failed
201	/// combine/derivation — is `Err(StagingCorrupt)`: the record may be the exact set a
202	/// prior attempt already bound to a genesis op and escrowed, so overwriting it with
203	/// unrelated shares would permanently destroy the recovery seed. The slot is
204	/// preserved for a later retry or manual inspection.
205	fn load_staged(
206	    account: &str,
207	    discriminator_a: &str,
208	    discriminator_b: &str,
209	) -> Result<Option<CeremonyShareSet>, ShareCeremonyError> {
210	    let bytes = match keychain::get_item(account) {
211	        Ok(bytes) => Zeroizing::new(bytes),
212	        Err(e) if keychain::is_not_found(&e) => return Ok(None),
213	        Err(e) => {
214	            tracing::error!(error = %e, "ceremony staging slot unreadable; failing closed");
215	            return Err(ShareCeremonyError::StagingCorrupt(format!(
216	                "keychain read failed: {e}"
217	            )));
218	        }
219	    };
220	    let record: StagingRecord = serde_json::from_slice(&bytes).map_err(|e| {
221	        tracing::error!(error = %e, "ceremony staging record unparseable; failing closed");
222	        ShareCeremonyError::StagingCorrupt(format!("unparseable staging record: {e}"))
223	    })?;
224	    if record.version != STAGING_VERSION {
225	        tracing::error!(
226	            version = record.version,
227	            "ceremony staging record has unsupported version; failing closed"
228	        );
229	        return Err(ShareCeremonyError::StagingCorrupt(format!(
230	            "unsupported staging record version {}",
231	            record.version
232	        )));
233	    }
234	    if record.handle != discriminator_a || record.pds_url != discriminator_b {
235	        tracing::warn!(
236	            "ceremony inputs changed since staging; abandoning the staged set and regenerating"
237	        );
238	        return Ok(None);
239	    }
240	
241	    let decode = |encoded: &str, index: u8| -> Result<crypto::ShareEnvelope, ShareCeremonyError> {
242	        match crypto::ShareEnvelope::decode_share(encoded) {
243	            Ok(env) if env.index() == index => Ok(env),
244	            Ok(env) => {
245	                tracing::error!(
246	                    expected = index,
247	                    got = env.index(),
248	                    "staged share has wrong index; failing closed"
249	                );
250	                Err(ShareCeremonyError::StagingCorrupt(format!(
251	                    "staged share has index {} where {index} was expected",
252	                    env.index()
253	                )))
254	            }
255	            Err(e) => {
256	                tracing::error!(error = %e, "staged share failed validation; failing closed");
257	                Err(ShareCeremonyError::StagingCorrupt(format!(
258	                    "staged share failed validation: {e}"
259	                )))
260	            }
261	        }
262	    };
263	    let env1 = decode(&record.share1, 1)?;
264	    let env2 = decode(&record.share2, 2)?;
265	    let env3 = decode(&record.share3, 3)?;
266	    if env1.set_id() != env2.set_id() || env2.set_id() != env3.set_id() {
267	        tracing::error!("staged shares span set_ids; failing closed");
268	        return Err(ShareCeremonyError::StagingCorrupt(
269	            "staged shares span set_ids".to_string(),
270	        ));
271	    }
272	
273	    // The seed is not stored — recompute it to re-derive the recovery key.
274	    let seed = crypto::combine_envelopes(&env1, &env2).map_err(|e| {
275	        tracing::error!(error = %e, "staged shares failed to combine; failing closed");
276	        ShareCeremonyError::StagingCorrupt(format!("staged shares failed to combine: {e}"))
277	    })?;
278	    let recovery = crypto::derive_recovery_keypair(&seed).map_err(|e| {
279	        tracing::error!(error = %e, "recovery key derivation failed on staged seed; failing closed");
280	        ShareCeremonyError::StagingCorrupt(format!("recovery key derivation failed: {e}"))
281	    })?;
282	
283	    tracing::info!(set_id = env1.set_id(), "reusing staged ceremony share set");
284	    Ok(Some(CeremonyShareSet {
285	        recovery_key_id: recovery.key_id.0,
286	        share1: env1.encode_share(),
287	        share2: env2.encode_share(),
288	        share3: env3.encode_share(),
289	        share3_words: env3.encode_share_words(),
290	    }))
291	}
292	
293	/// Tear down the *create*-ceremony staging slot — the seed material's last transient
294	/// home. Idempotent: an absent slot is success (the teardown already happened).
295	pub fn clear_staging() -> Result<(), keychain::KeychainError> {
296	    clear_staging_account(STAGING_ACCOUNT)
297	}
298	
299	/// Tear down the per-DID re-key staging slot. Idempotent, like [`clear_staging`].
300	pub fn clear_rekey_staging(did: &str) -> Result<(), keychain::KeychainError> {
301	    clear_staging_account(&rekey_staging_account(did))
302	}
303	
304	/// Whether a per-DID re-key staging slot exists — i.e. a re-key was started for this DID and has
305	/// not yet been confirmed/torn down. Used to resurface the "finish your upgrade" prompt when a
306	/// re-key was interrupted after its PLC op landed (so the identity already reads as new-model) but
307	/// before escrow/Share 1/confirmation completed. A transient keychain read error reads as "not in
308	/// progress" (fail-open for a prompt is safe — the account is never worse off un-prompted).
309	pub fn rekey_staging_exists(did: &str) -> bool {
310	    keychain::get_item(&rekey_staging_account(did)).is_ok()
311	}
312	
313	fn clear_staging_account(account: &str) -> Result<(), keychain::KeychainError> {
314	    match keychain::delete_item(account) {
315	        Ok(()) => Ok(()),
316	        Err(e) if keychain::is_not_found(&e) => Ok(()),
317	        Err(e) => Err(e),
318	    }
319	}
