321	#[cfg(test)]
322	mod tests {
323	    use super::*;
324	
325	    const HANDLE: &str = "alice.example.com";
326	    const PDS: &str = "https://pds.example.com";
327	
328	    #[test]
329	    fn generates_and_stages_a_valid_set() {
330	        keychain::clear_for_test();
331	        let set = load_or_create(HANDLE, PDS).unwrap();
332	
333	        // All three envelopes decode, share the same set_id, and carry their indices.
334	        let env1 = crypto::ShareEnvelope::decode_share(&set.share1).unwrap();
335	        let env2 = crypto::ShareEnvelope::decode_share(&set.share2).unwrap();
336	        let env3 = crypto::ShareEnvelope::decode_share(&set.share3).unwrap();
337	        assert_eq!(env1.index(), 1);
338	        assert_eq!(env2.index(), 2);
339	        assert_eq!(env3.index(), 3);
340	        assert_eq!(env1.set_id(), env2.set_id());
341	        assert_eq!(env2.set_id(), env3.set_id());
342	
343	        // The word phrase encodes the same envelope as the base32 form.
344	        let from_words = crypto::ShareEnvelope::decode_share_words(&set.share3_words).unwrap();
345	        assert_eq!(from_words.set_id(), env3.set_id());
346	        assert_eq!(from_words.index(), 3);
347	
348	        // Any two shares reconstruct a seed whose derived key matches the declared one.
349	        let seed = crypto::combine_envelopes(&env1, &env3).unwrap();
350	        let derived = crypto::derive_recovery_keypair(&seed).unwrap();
351	        assert_eq!(derived.key_id.0, set.recovery_key_id);
352	    }
353	
354	    #[test]
355	    fn retry_reuses_the_staged_set() {
356	        keychain::clear_for_test();
357	        let first = load_or_create(HANDLE, PDS).unwrap();
358	        let second = load_or_create(HANDLE, PDS).unwrap();
359	        assert_eq!(*first.share1, *second.share1, "retry must reuse Share 1");
360	        assert_eq!(*first.share2, *second.share2, "retry must reuse Share 2");
361	        assert_eq!(*first.share3, *second.share3, "retry must reuse Share 3");
362	        assert_eq!(first.recovery_key_id, second.recovery_key_id);
363	        let set_id = |s: &str| crypto::ShareEnvelope::decode_share(s).unwrap().set_id();
364	        assert_eq!(
365	            set_id(&first.share2),
366	            set_id(&second.share2),
367	            "same set_id across retries — no orphaned escrow"
368	        );
369	    }
370	
371	    #[test]
372	    fn changed_ceremony_inputs_regenerate() {
373	        keychain::clear_for_test();
374	        let first = load_or_create(HANDLE, PDS).unwrap();
375	        let other = load_or_create("bob.example.com", PDS).unwrap();
376	        assert_ne!(
377	            *first.share2, *other.share2,
378	            "a different ceremony must not reuse the old set"
379	        );
380	    }
381	
382	    #[test]
383	    fn corrupt_staging_record_fails_closed_and_preserves_the_slot() {
384	        keychain::clear_for_test();
385	        load_or_create(HANDLE, PDS).unwrap();
386	        keychain::store_item(STAGING_ACCOUNT, b"not json").unwrap();
387	        // A present-but-unreadable record must never be overwritten with fresh
388	        // material — it may be the set a prior attempt already escrowed.
389	        // (CeremonyShareSet has no Debug — share material must not be printable.)
390	        let err = load_or_create(HANDLE, PDS)
391	            .map(|_| ())
392	            .expect_err("corrupt staging must fail closed");
393	        assert!(matches!(err, ShareCeremonyError::StagingCorrupt(_)));
394	        assert_eq!(
395	            keychain::get_item(STAGING_ACCOUNT).unwrap(),
396	            b"not json".to_vec(),
397	            "the staging slot must be preserved for inspection/retry"
398	        );
399	    }
400	
401	    #[test]
402	    fn tampered_staged_share_fails_closed() {
403	        keychain::clear_for_test();
404	        let first = load_or_create(HANDLE, PDS).unwrap();
405	        // Corrupt one envelope inside an otherwise valid record: the checksum check
406	        // must fail the load closed rather than regenerate. Flip share2's first
407	        // character to a different base32 character (deterministic corruption).
408	        let flipped_first = if first.share2.starts_with('A') {
409	            "B"
410	        } else {
411	            "A"
412	        };
413	        let mut corrupt_share2 = first.share2.to_string();
414	        corrupt_share2.replace_range(0..1, flipped_first);
415	        let bytes = keychain::get_item(STAGING_ACCOUNT).unwrap();
416	        let tampered = String::from_utf8(bytes)
417	            .unwrap()
418	            .replace(&*first.share2, &corrupt_share2);
419	        keychain::store_item(STAGING_ACCOUNT, tampered.as_bytes()).unwrap();
420	        assert!(matches!(
421	            load_or_create(HANDLE, PDS),
422	            Err(ShareCeremonyError::StagingCorrupt(_))
423	        ));
424	        // The envelope-validation failure path preserves the slot exactly like the
425	        // JSON-corruption path — the record is never overwritten with fresh material.
426	        assert_eq!(
427	            keychain::get_item(STAGING_ACCOUNT).unwrap(),
428	            tampered.as_bytes().to_vec(),
429	            "the tampered staging record must be preserved for inspection/retry"
430	        );
431	    }
432	
433	    #[test]
434	    fn clear_staging_is_idempotent() {
435	        keychain::clear_for_test();
436	        load_or_create(HANDLE, PDS).unwrap();
437	        clear_staging().unwrap();
438	        assert!(matches!(
439	            keychain::get_item(STAGING_ACCOUNT),
440	            Err(ref e) if keychain::is_not_found(e)
441	        ));
442	        clear_staging().unwrap();
443	    }
444	
445	    const DID_A: &str = "did:plc:aaaaaaaaaaaaaaaaaaaaaaaa";
446	    const DID_B: &str = "did:plc:bbbbbbbbbbbbbbbbbbbbbbbb";
447	
448	    #[test]
449	    fn rekey_staging_is_scoped_per_did() {
450	        keychain::clear_for_test();
451	        // Two identities re-keying concurrently must not share a staging slot: each
452	        // reloads its own set, and neither abandons the other's.
453	        let a = load_or_create_for_rekey(DID_A, PDS).unwrap();
454	        let b = load_or_create_for_rekey(DID_B, PDS).unwrap();
455	        assert_ne!(*a.share2, *b.share2, "distinct DIDs get distinct sets");
456	
457	        let a_again = load_or_create_for_rekey(DID_A, PDS).unwrap();
458	        assert_eq!(
459	            *a.share2, *a_again.share2,
460	            "DID A's set survives DID B's re-key staging"
461	        );
462	        assert_eq!(a.recovery_key_id, a_again.recovery_key_id);
463	    }
464	
465	    #[test]
466	    fn rekey_staging_does_not_collide_with_create_staging() {
467	        keychain::clear_for_test();
468	        let create = load_or_create(HANDLE, PDS).unwrap();
469	        let rekey = load_or_create_for_rekey(DID_A, PDS).unwrap();
470	        assert_ne!(
471	            *create.share2, *rekey.share2,
472	            "create and re-key ceremonies use independent slots"
473	        );
474	        // Clearing the re-key slot leaves the create slot intact and vice versa.
475	        clear_rekey_staging(DID_A).unwrap();
476	        assert!(keychain::get_item(STAGING_ACCOUNT).is_ok());
477	        assert_eq!(
478	            *load_or_create(HANDLE, PDS).unwrap().share2,
479	            *create.share2,
480	            "create staging is untouched by re-key teardown"
481	        );
482	    }
483	
484	    #[test]
485	    fn clear_rekey_staging_is_idempotent() {
486	        keychain::clear_for_test();
487	        load_or_create_for_rekey(DID_A, PDS).unwrap();
488	        clear_rekey_staging(DID_A).unwrap();
489	        assert!(matches!(
490	            keychain::get_item(&rekey_staging_account(DID_A)),
491	            Err(ref e) if keychain::is_not_found(e)
492	        ));
493	        clear_rekey_staging(DID_A).unwrap();
494	    }
495	}
